import { anonymousCheckpointState, anonymousInferenceState } from "../../../../supabase/functions/_shared/anonymous-memory-expiry";
import { TemporaryStateUnavailableError, temporaryStateMessage } from "../../../../lib/temporary-state-error";
import { maintenanceResponse } from "../../../../lib/maintenance";
import { createClient } from "@supabase/supabase-js";
import { createServerSupabase, loadCanonicalState, openTemporaryState, sealTemporaryState, type RootState, loadTemporaryRoot, loadCompletedTemporaryTurn, editTemporaryRoot, forgetControlPayload } from "../../../../lib/canonical-state";
import { createForgetJudge, identifyForgetTargets, addForgetControls } from "../../../../supabase/functions/_shared/forget-control";

async function authenticate(request: Request) {
  const token = request.headers.get("authorization")?.match(/^Bearer (.+)$/)?.[1];
  if (!token) return null;
  const db = createClient("https://tzozajnwznxqgxnjikoy.supabase.co", "sb_publishable_ZEYZ3tc1RLE7EuClbUP4vA_ISHWfKr1", {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
  });
  const { data, error } = await db.auth.getUser(token);
  return error ? null : data.user;
}
function responseState(state: RootState, ephemeral = false) {
  const history = state.history ?? [];
  const active = ephemeral ? anonymousInferenceState(state, Date.now()) : state;
  return { exists: true, history, memory: active.memory, relationshipPoints: active.relationshipPoints,
    misakiTodayMemory: active.todayMemory, ephemeral, messageCount: history.length,
    userMessageCount: history.filter((item: any) => item?.role === "user").length, memoryCount: active.memory.length, updatedAt: state.updatedAt ?? null };
}
export async function GET(request: Request) {
  try {
    const user = await authenticate(request);
    if (!user) return Response.json({ error: "Authentication required." }, { status: 401 });
    if (user.is_anonymous) return Response.json({ exists: false, ephemeral: true }, { headers: { "Cache-Control": "no-store" } });
    return Response.json(responseState(await loadCanonicalState(user.id, "history")), { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    console.error("CONVERSATION STATE READ FAILED", { code: "STATE_READ_FAILED" });
    return Response.json({ error: "Conversation state could not be loaded." }, { status: 500 });
  }
}
export async function POST(request: Request) {
  // Monotonic timings only; never include identifiers or conversation contents.
  const nowMs = () => typeof performance !== "undefined" ? performance.now() : Date.now();
  const requestStartedAt = nowMs();
  // Anonymous "load" renews the root, so it is a write too.
  try {
    const [maintenance, { user, authenticatedAt }] = await Promise.all([
      maintenanceResponse(),
      authenticate(request).then(user => ({ user, authenticatedAt: nowMs() })),
    ]);
    if (maintenance) return maintenance;
    if (!user) return Response.json({ error: "Authentication required." }, { status: 401 });
    const body = await request.json();
    if (body.saveAnonymous === true) {
      if (!user.is_anonymous || body.expectedUserId !== user.id) {
        return Response.json({ error: "Anonymous account mismatch." }, { status: 409 });
      }
      let state = await loadTemporaryRoot(user.id, body.temporaryState);
      // A reply can have committed even if its transport response was lost.
      if (typeof body.pending?.requestId === "string" && typeof body.pending?.message === "string") {
        const replay = await loadCompletedTemporaryTurn(user.id, body.pending.requestId, body.pending.message, body.pending.temporaryState);
        if (replay) {
          const recovered = openTemporaryState(replay.temporaryState);
          if (recovered) state = await loadTemporaryRoot(user.id, replay.temporaryState);
        }
      }
      const active = anonymousCheckpointState(state, Date.now());
      const { data, error } = await createServerSupabase().rpc("save_misaki_temporary_state", {
        p_user_id: user.id, p_history: active.history, p_memory: active.memory,
        p_today_memory: active.todayMemory, p_points: active.relationshipPoints,
        p_relationship: active.temporaryRelationship,
        p_expected_revision: state.temporaryRevision ?? null,
        p_forget_payload: await forgetControlPayload(user.id, state.forgetControls ?? []),
      });
      if (error) {
        console.error("EMAIL CHECKPOINT ERROR", { code: "STATE_COMMIT_FAILED" });
        throw new Error("Email checkpoint failed");
      }
      return Response.json({ synced: true, result: data });
    }
    if (body.action === "load") {
      const loadStartedAt = nowMs();
      const timedResponse = (payload: unknown) => Response.json(payload, {
        headers: { "Cache-Control": "no-store", "Server-Timing": [
          `auth;dur=${(authenticatedAt - requestStartedAt).toFixed(1)}`,
          `history;dur=${(nowMs() - loadStartedAt).toFixed(1)}`,
          `request;dur=${(nowMs() - requestStartedAt).toFixed(1)}`,
        ].join(", ") },
      });
      if (user.is_anonymous && typeof body.pending?.requestId === "string" && typeof body.pending?.message === "string") {
        const replay = await loadCompletedTemporaryTurn(user.id, body.pending.requestId, body.pending.message, body.pending.temporaryState);
        if (replay) {
          const recovered = openTemporaryState(replay.temporaryState);
          if (recovered) {
            const latest = await loadTemporaryRoot(user.id, replay.temporaryState);
            return timedResponse({ ...responseState(latest, true),
              temporaryState: latest.temporaryRevision ? await editTemporaryRoot(user.id, latest, "load") : sealTemporaryState(latest, "load"), recoveredTurn: true });
          }
        }
      }
      const state = user.is_anonymous ? await loadTemporaryRoot(user.id, body.temporaryState) : await loadCanonicalState(user.id, "history");
      return timedResponse({ ...responseState(state, !!user.is_anonymous),
        ...(user.is_anonymous ? { temporaryState: state.temporaryRevision ? await editTemporaryRoot(user.id, state, "load") : sealTemporaryState(state, "load") } : {}) });
    }
    if (!["deleteMemory", "clearMemory", "clearHistory"].includes(body.action) ||
      (body.action === "deleteMemory" && typeof body.value !== "string")) {
      return Response.json({ error: "Explicit state operation required." }, { status: 400 });
    }
    const state = user.is_anonymous ? await loadTemporaryRoot(user.id, body.temporaryState) : await loadCanonicalState(user.id);
    const requestId = typeof body.requestId === "string" && /^[0-9a-f-]{36}$/i.test(body.requestId) ? body.requestId : crypto.randomUUID();
    if (body.action !== "clearHistory") {
      const items = body.action === "clearMemory" ? state.memory : state.memory.filter(item => item === body.value);
      const judge = createForgetJudge(process.env.GEMINI_API_KEY!);
      let controls = state.forgetControls ?? [];
      for (const item of items) {
        const targets = await identifyForgetTargets("UI explicitly deletes all facts in this item", [{ text: item }], judge);
        if (!targets.length) throw new Error("Memory deletion target could not be safely identified");
        controls = await addForgetControls(controls, targets.map(t => ({ ...t, scope: "fact" as const })), "hard_delete", requestId, new Date().toISOString(), `${process.env.SUPABASE_SERVICE_ROLE_KEY}:${user.id}`);
      }
      state.forgetControls = controls;
    }
    if (user.is_anonymous) {
      if (body.action === "clearHistory") state.history = [];
      else state.memory = body.action === "clearMemory" ? [] : state.memory.filter(item => item !== body.value);
      return Response.json({ ...responseState(state, true), temporaryState: await editTemporaryRoot(user.id, state) });
    }
    const { error } = await createServerSupabase().rpc("edit_misaki_conversation_state", {
      p_user_id: user.id, p_action: body.action, p_value: body.value ?? null,
      p_expected_updated_at: state.updatedAt ?? null,
      p_forget_payload: await forgetControlPayload(user.id, state.forgetControls ?? []),
    });
    if (error) throw new Error("Conversation edit failed");
    return Response.json(responseState(await loadCanonicalState(user.id, "history")));
  } catch (error) {
    if (error instanceof TemporaryStateUnavailableError) {
      const status = error.reason === "expired" ? 410 : 409;
      const code = error.reason === "expired" ? "TEMPORARY_STATE_EXPIRED" : "TEMPORARY_STATE_UNVERIFIABLE";
      console.error("CONVERSATION STATE UNAVAILABLE", { code, status });
      return Response.json({ code, error: temporaryStateMessage(status, { code }) },
        { status, headers: { "Cache-Control": "no-store" } });
    }
    // Never log arbitrary exception payloads (may contain private data).
    console.error("CONVERSATION STATE WRITE FAILED", { code: "STATE_OPERATION_FAILED" });
    return Response.json({ error: "Conversation state could not be saved." }, { status: 500 });
  }
}

